import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.CbQjVMS6.js";const u=JSON.parse('{"title":"About PieTeams","description":"","frontmatter":{},"headers":[],"relativePath":"about.md","filePath":"about.md","lastUpdated":1794023466000}'),n={name:"about.md"};function r(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="about-pieteams" tabindex="-1">About PieTeams <a class="header-anchor" href="#about-pieteams" aria-label="Permalink to &quot;About PieTeams&quot;">​</a></h1><p>PieTeams is an independent open-source team. We design and publish software for knowledge management, master data and product lifecycle management.</p><p>The organisation lives on GitHub at <a href="https://github.com/pieteams" target="_blank" rel="noreferrer">github.com/pieteams</a>. This website is the shared home for the projects, their documentation and the ideas behind them.</p><h2 id="why-we-exist" tabindex="-1">Why we exist <a class="header-anchor" href="#why-we-exist" aria-label="Permalink to &quot;Why we exist&quot;">​</a></h2><p>Organisations generate more documents, records and product data than ever, yet most of that information remains trapped in folders, spreadsheets and proprietary systems. The result is familiar:</p><ul><li>people cannot find the document they know exists</li><li>two departments maintain different versions of the same customer record</li><li>an AI assistant retrieves plausible text but cannot show where it came from</li><li>a small manufacturer gives up on PLM because the suite costs more than the product line</li></ul><p>Our projects attack these problems with small, explicit systems. We prefer plain files and documented interfaces over opaque platforms. We prefer software that a competent team can run and inspect over software that must be trusted blindly.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><h3 id="_1-explicit-knowledge" tabindex="-1">1. Explicit knowledge <a class="header-anchor" href="#_1-explicit-knowledge" aria-label="Permalink to &quot;1. Explicit knowledge&quot;">​</a></h3><p>PieKBS stores knowledge as Markdown. PieMDM stores master data in relational tables with versioned definitions. PiePLM writes its design down before writing code. In each case, the important information is visible and reviewable.</p><h3 id="_2-boring-technology" tabindex="-1">2. Boring technology <a class="header-anchor" href="#_2-boring-technology" aria-label="Permalink to &quot;2. Boring technology&quot;">​</a></h3><p>Go, SQLite, MySQL, PostgreSQL, HTTP and Markdown are well understood. They are easy to hire for, easy to operate and unlikely to disappear. We use AI where it adds value, not as a reason to discard engineering fundamentals.</p><h3 id="_3-local-first-and-self-hostable" tabindex="-1">3. Local-first and self-hostable <a class="header-anchor" href="#_3-local-first-and-self-hostable" aria-label="Permalink to &quot;3. Local-first and self-hostable&quot;">​</a></h3><p>Our software is designed to run on a laptop, an internal server or a private cloud. A team should not lose access to its own knowledge because a vendor changes its pricing.</p><h3 id="_4-open-source-open-discussion" tabindex="-1">4. Open source, open discussion <a class="header-anchor" href="#_4-open-source-open-discussion" aria-label="Permalink to &quot;4. Open source, open discussion&quot;">​</a></h3><p>All projects are MIT licensed. Issues, design notes and roadmap discussions happen in public repositories. We review contributions on their technical merits.</p><h2 id="how-we-work" tabindex="-1">How we work <a class="header-anchor" href="#how-we-work" aria-label="Permalink to &quot;How we work&quot;">​</a></h2><ul><li>Each project has a single maintainer-led roadmap.</li><li>Changes are proposed as pull requests and reviewed before merge.</li><li>Documentation is part of the change, not an afterthought.</li><li>Releases are tagged and published with build artifacts where applicable.</li></ul><h2 id="independence-and-funding" tabindex="-1">Independence and funding <a class="header-anchor" href="#independence-and-funding" aria-label="Permalink to &quot;Independence and funding&quot;">​</a></h2><p>PieTeams is not affiliated with any vendor whose products appear in our documentation. This website displays advertising through Google AdSense to support hosting and maintenance. Advertising does not influence project documentation, comparisons or recommendations.</p><h2 id="editorial-policy" tabindex="-1">Editorial policy <a class="header-anchor" href="#editorial-policy" aria-label="Permalink to &quot;Editorial policy&quot;">​</a></h2><p>Our comparison pages describe third-party products using publicly available information. We aim to be accurate and fair. If you believe a statement is outdated or incorrect, open an issue in the relevant repository; corrections are welcome and will be reviewed.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>The fastest way to reach us is through GitHub issues. See the <a href="/contact">contact page</a>. For information about data handling and advertising, read the <a href="/privacy">privacy policy</a>.</p>',24)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
